package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;import java.io.*;
public final class PcSceneReferenceExport {
 static void buffer(DataOutputStream out,ByteBuffer b)throws Exception{byte[] data=new byte[b.remaining()];b.duplicate().get(data);out.writeInt(data.length);out.write(data);}
 static void floats(DataOutputStream out,FloatBuffer f)throws Exception{out.writeInt(f.remaining()*4);while(f.hasRemaining())out.writeInt(Integer.reverseBytes(Float.floatToRawIntBits(f.get())));}
 public static void main(String[] args)throws Exception{Path output=Paths.get(args[1]);Files.createDirectories(output);int scenes=0,commands=0;try(DirectoryStream<Path> files=Files.newDirectoryStream(Paths.get(args[0]),"source-race-background-*.nrb")){for(Path file:files){NativeBackgroundScene bg=new NativeBackgroundScene(Files.readAllBytes(file));NativeSceneSnapshot s=bg.sky.scene;NativeSceneComposition composition=new NativeSceneComposition(s);int total=0;for(int owner=0;owner<composition.count();owner++)total+=composition.plan(owner).count();try(DataOutputStream out=new DataOutputStream(Files.newOutputStream(output.resolve(s.refresh+".scene")))){out.writeLong(s.epoch);out.writeLong(s.refresh);out.writeInt(composition.count());out.writeInt(s.splitRow);out.writeInt(total);buffer(out,bg.exactRgba());buffer(out,NativeHistoricalPalette.rgba(s));for(int owner=0;owner<composition.count();owner++){NativeSceneDrawPlan plan=composition.plan(owner);for(int i=0;i<plan.count();i++){NativeSceneDrawPlan.Draw d=plan.draw(i);NativeDrawBounds b=d.bounds;long[] info={owner,d.model?1:0,d.index,d.width,d.height,d.vertices,d.indexed?1:0,d.wall?1:0,d.lighting!=null?1:0,b.left,b.right,b.top,b.bottom,owner==0?0:s.splitRow,composition.count()==1||owner==1?160:s.splitRow,i};for(long v:info)out.writeLong(v);floats(out,d.mesh());out.writeInt(d.vertices/3*44);for(int t=0;t<d.vertices;t+=3){NativeTexturePlane p=new NativeTexturePlane(d.mesh(),t);for(float v:new float[]{p.x,p.y})out.writeInt(Integer.reverseBytes(Float.floatToRawIntBits(v)));for(float[] a:new float[][]{p.base,p.dx,p.dy})for(float v:a)out.writeInt(Integer.reverseBytes(Float.floatToRawIntBits(v)));}int levels=d.lighting==null?1:16;out.writeInt(levels);for(int level=0;level<levels;level++)buffer(out,d.lighting==null?d.image():d.lighting.variant(level));if(d.lighting!=null&&d.lighting.curve!=null){out.writeInt(2);for(int width:new int[]{240,3240}){out.writeInt(width);for(int level:d.lighting.curve.columns(width))out.writeInt(Integer.reverseBytes(level));}}else out.writeInt(0);commands++;}}}scenes++;}}if(scenes!=9)throw new AssertionError();System.out.println("PASS_PC_SCENE_EXPORT scenes="+scenes+" commands="+commands);}
}
